<script setup lang="ts">
const props=defineProps<{series:{month:string;invoiced:number;collected:number}[]}>()
const peak=computed(()=>Math.max(1,...props.series.flatMap(s=>[s.invoiced,s.collected])))
function points(key:'invoiced'|'collected'){return props.series.map((s,i)=>`${props.series.length===1?500:i/(props.series.length-1)*1000},${220-s[key]/peak.value*200}`).join(' ')}
const total=computed(()=>props.series.reduce((sum,s)=>sum+s.collected,0))
</script>
<template><UCard :ui="{body:'!p-0',header:'border-0'}"><template #header><p class="text-xs font-medium text-muted uppercase mb-1">Collected revenue</p><p class="text-3xl font-semibold text-highlighted">{{money(total)}}</p><div class="flex gap-4 text-xs text-muted mt-3"><span class="flex items-center gap-1.5"><span class="size-2 rounded-full bg-primary"/>Collected</span><span class="flex items-center gap-1.5"><span class="size-2 rounded-full bg-muted border border-accented"/>Invoiced</span></div></template><div class="px-4 sm:px-6 pb-5"><svg v-if="series.length" viewBox="0 0 1000 240" preserveAspectRatio="none" class="w-full h-56 sm:h-72 overflow-visible" role="img" aria-label="Collected revenue and invoiced totals over time"><defs><linearGradient id="revenue-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="var(--ui-primary)" stop-opacity=".2"/><stop offset="100%" stop-color="var(--ui-primary)" stop-opacity="0"/></linearGradient></defs><line v-for="y in [20,70,120,170,220]" :key="y" x1="0" x2="1000" :y1="y" :y2="y" stroke="var(--ui-border)" stroke-dasharray="3 5"/><polygon :points="`0,240 ${points('collected')} 1000,240`" fill="url(#revenue-fill)"/><polyline :points="points('invoiced')" fill="none" stroke="var(--ui-text-dimmed)" stroke-width="1.5" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/><polyline :points="points('collected')" fill="none" stroke="var(--ui-primary)" stroke-width="2" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg><p v-else class="py-20 text-center text-muted">No revenue history in this period.</p><div class="flex justify-between text-xs text-dimmed mt-2"><span v-for="s in series" :key="s.month">{{s.month}}</span></div></div></UCard></template>
